(() => {
'use strict';
const canvas = document.getElementById('game'), ctx = canvas.getContext('2d');
const $ = id => document.getElementById(id);
const ui = {
  health:$('health-value'), hunger:$('hunger-value'), thirst:$('thirst-value'), healthBar:$('health-bar'), hungerBar:$('hunger-bar'), thirstBar:$('thirst-bar'),
  day:$('day-label'), time:$('time-label'), objective:$('objective-text'), progress:$('objective-progress'), log:$('event-log'), toast:$('toast'), prompt:$('interaction-prompt'), promptName:$('prompt-name'), threat:$('threat-badge'), resources:$('resource-list'), recipes:$('recipe-list'),
  start:$('start-screen'), over:$('game-over'), endTitle:$('end-title'), endCopy:$('end-copy'), pack:$('pack-count'), weather:$('weather-icon'), win:$('win-note')
};
const ITEM = {
  wood:{name:'Wood',icon:'♣'},stone:{name:'Stone',icon:'⬟'},fiber:{name:'Fiber',icon:'≋'},berries:{name:'Berries',icon:'●'},water:{name:'Fresh water',icon:'◉'},
  thatch:{name:'Thatch',icon:'〰'}
};
const recipes = [
  {id:'spear',name:'Stone spear',icon:'↗',cost:{wood:3,stone:2,fiber:1},kind:'tool',desc:'A sharp point for keeping teeth at a distance.'},
  {id:'axe',name:'Hand axe',icon:'⚒',cost:{wood:2,stone:2,fiber:2},kind:'tool',desc:'Chop trees for extra wood.'},
  {id:'campfire',name:'Campfire',icon:'♨',cost:{wood:5,stone:3},kind:'build',desc:'Warmth, light, and a safer night.'},
  {id:'wall',name:'Wood wall',icon:'▥',cost:{wood:4},kind:'build',desc:'A sturdy barrier between you and danger.'},
  {id:'shelter',name:'Lean-to',icon:'⌂',cost:{wood:7,thatch:3},kind:'build',desc:'A dry place to survive the night.'},
  {id:'flask',name:'Water flask',icon:'♧',cost:{fiber:3},kind:'tool',desc:'Hold a little more fresh water.'}
];
let W=0,H=0,dpr=1,last=0,elapsed=0,gameStarted=false,gameEnded=false,toastTimer=0,attackFlash=0;
const world={rx:1090,ry:790};
const player={x:0,y:0,r:13,speed:178,health:100,hunger:100,thirst:100,wood:0,stone:0,fiber:0,berries:0,water:0,thatch:0,hasSpear:false,hasAxe:false,hasFlask:false,dirX:0,dirY:1};
let nodes=[],dinos=[],buildings=[],particles=[],keys={},selectedBuild='campfire',nearest=null,dayWon=false,stats={wood:0},joystick={x:0,y:0};
function rand(a,b){return a+Math.random()*(b-a)}
function inIsland(x,y,margin=0){const rx=world.rx-margin,ry=world.ry-margin;return (x*x)/(rx*rx)+(y*y)/(ry*ry)<1}
function islandPoint(min=80,max=1){let a=rand(0,Math.PI*2),r=Math.sqrt(rand(min,Math.max(min,max)));return{x:Math.cos(a)*world.rx*r,y:Math.sin(a)*world.ry*r}}
function makeNode(type,x,y){const n={type,x,y,alive:true,scale:rand(.8,1.2),variant:Math.floor(rand(0,3)),sway:rand(0,6)};nodes.push(n);return n}
function seedWorld(){
  nodes=[];dinos=[];buildings=[];particles=[];
  for(let i=0;i<35;i++){let p=islandPoint(.28,.92);makeNode('tree',p.x,p.y)}
  for(let i=0;i<25;i++){let p=islandPoint(.18,.93);makeNode('rock',p.x,p.y)}
  for(let i=0;i<20;i++){let p=islandPoint(.25,.91);makeNode('fiber',p.x,p.y)}
  for(let i=0;i<14;i++){let p=islandPoint(.25,.88);makeNode('berry',p.x,p.y)}
  // Little freshwater springs tucked into the island's inner green.
  for(const p of [{x:-380,y:140},{x:360,y:-210},{x:190,y:360}]){nodes.push({type:'spring',x:p.x,y:p.y,alive:true,scale:1,variant:0,sway:0})}
  for(let i=0;i<5;i++){let p=islandPoint(.45,.82);dinos.push({x:p.x,y:p.y,vx:rand(-1,1),vy:rand(-1,1),angle:rand(0,6),speed:rand(32,46),hp:3,alive:true,alert:0,attack:0,roam:rand(0,3),scale:rand(.88,1.12)})}
}
function resetGame(){Object.assign(player,{x:0,y:0,health:100,hunger:100,thirst:100,wood:0,stone:0,fiber:0,berries:0,water:0,thatch:0,hasSpear:false,hasAxe:false,hasFlask:false,dirX:0,dirY:1});elapsed=0;gameEnded=false;dayWon=false;gameStarted=true;stats.wood=0;selectedBuild='campfire';seedWorld();document.querySelectorAll('.build-slot').forEach(b=>b.classList.toggle('active',b.dataset.build==='campfire'));ui.start.classList.add('hidden');ui.over.classList.add('hidden');ui.win.classList.remove('visible');ui.log.innerHTML='<div class="log-empty">Your field notes will appear here as you explore.</div>';addLog('Washed ashore. Time to find supplies.');showToast('You made it to shore. Stay alive.');updateUI()}
function addLog(text){const blank=ui.log.querySelector('.log-empty');if(blank)blank.remove();const d=document.createElement('div');d.className='log-entry';const t=new Date();const clock=`${String(Math.floor(elapsed/60)).padStart(2,'0')}:${String(Math.floor(elapsed%60)).padStart(2,'0')}`;d.innerHTML=`<span class="log-time">${clock}</span><span>${text}</span>`;ui.log.prepend(d);while(ui.log.children.length>5)ui.log.lastChild.remove()}
function showToast(text){ui.toast.textContent=text;ui.toast.classList.add('show');toastTimer=2.1}
function resourceTotal(){return ['wood','stone','fiber','berries','water','thatch'].reduce((a,k)=>a+player[k],0)}
function canPay(cost){return Object.entries(cost).every(([k,n])=>player[k]>=n)}
function pay(cost){for(const [k,n] of Object.entries(cost))player[k]-=n}
function costText(cost){return Object.entries(cost).map(([k,n])=>`${ITEM[k]?.icon||''} ${n} ${ITEM[k]?.name||k}`).join(' · ')}
function buildRecipeUI(){ui.recipes.innerHTML='';for(const r of recipes){const row=document.createElement('div');row.className='recipe';row.innerHTML=`<span class="recipe-icon">${r.icon}</span><span><b class="recipe-name">${r.name}</b><small class="recipe-cost">${costText(r.cost)}</small></span><button type="button" data-craft="${r.id}">${r.kind==='build'?'MAKE':'CRAFT'}</button>`;ui.recipes.appendChild(row)}ui.recipes.addEventListener('click',e=>{const b=e.target.closest('[data-craft]');if(b)craft(b.dataset.craft)})}
function updateUI(){
  for(const [key,el,bar] of [['health',ui.health,ui.healthBar],['hunger',ui.hunger,ui.hungerBar],['thirst',ui.thirst,ui.thirstBar]]){const val=Math.max(0,Math.ceil(player[key]));el.textContent=val;bar.style.width=val+'%';bar.style.background=key==='health'?'#c77865':key==='hunger'?'#9a9b5b':'#69a5a3'}
  const resources=['wood','stone','fiber','berries','water','thatch'];ui.resources.innerHTML=resources.map(k=>`<div class="resource-card" data-key="${k}"><span class="resource-icon">${ITEM[k].icon}</span><span class="resource-meta"><span class="resource-name">${ITEM[k].name.toUpperCase()}</span><b class="resource-amount">${player[k]}</b></span></div>`).join('');ui.pack.textContent=`${resourceTotal()} / 40`;
  document.querySelectorAll('.recipe').forEach(row=>{const r=recipes.find(x=>x.id===row.querySelector('button').dataset.craft),b=row.querySelector('button');const available=canPay(r.cost)&&!((r.id==='spear'&&player.hasSpear)||(r.id==='axe'&&player.hasAxe)||(r.id==='flask'&&player.hasFlask));b.disabled=!available;b.textContent=(r.id==='spear'&&player.hasSpear)||(r.id==='axe'&&player.hasAxe)||(r.id==='flask'&&player.hasFlask)?'MADE':r.kind==='build'?'MAKE':'CRAFT'});
  const time=(7*60+20+Math.floor(elapsed*1.6))%(24*60);ui.time.textContent=`${String(Math.floor(time/60)).padStart(2,'0')}:${String(time%60).padStart(2,'0')}`;const day=Math.floor(elapsed/150)+1;ui.day.textContent=`DAY ${String(day).padStart(2,'0')}`;const night=(time<6*60||time>19*60);ui.weather.textContent=night?'☾':'☀';
  const goal=stats.wood<5?`Gather ${5-stats.wood} more wood to begin`:!player.hasSpear?'Craft a spear to defend yourself':!buildings.some(b=>b.type==='shelter')?'Build a lean-to before nightfall':'Survive until dawn';ui.objective.textContent=goal;ui.progress.textContent=stats.wood<5?`${Math.min(stats.wood,5)} / 5 collected`:player.hasSpear?'Spear ready · keep gathering':'Shelter is your safe haven';
}
function craft(id){const r=recipes.find(x=>x.id===id);if(!r)return;if(!canPay(r.cost)){showToast(`Need ${costText(r.cost)}`);return}if(id==='spear'&&player.hasSpear||id==='axe'&&player.hasAxe||id==='flask'&&player.hasFlask)return;pay(r.cost);if(id==='spear')player.hasSpear=true;if(id==='axe')player.hasAxe=true;if(id==='flask')player.hasFlask=true;if(id==='flask')showToast('Water flask crafted · +10 capacity');else if(r.kind==='build'){selectedBuild=id;setSelectedBuild(id);showToast(`${r.name} ready to place · click nearby ground`)}else showToast(`${r.name} crafted`);addLog(`Crafted ${r.name.toLowerCase()}.`);updateUI()}
function setSelectedBuild(id){selectedBuild=id;document.querySelectorAll('.build-slot').forEach(b=>b.classList.toggle('active',b.dataset.build===id))}
function resize(){const rect=canvas.getBoundingClientRect();if(!rect.width||!rect.height)return;dpr=Math.min(window.devicePixelRatio||1,2);W=rect.width;H=rect.height;canvas.width=Math.round(W*dpr);canvas.height=Math.round(H*dpr);ctx.setTransform(dpr,0,0,dpr,0,0)}
window.addEventListener('resize',resize);new ResizeObserver(resize).observe(canvas);

