function gather(){const target=nearestTarget();if(!target||target.dist>72){showToast('Nothing close enough to gather');return}const n=target.node;let amount=1,label='';if(n.type==='tree'){amount=player.hasAxe?3:2;player.wood+=amount;stats.wood+=amount;label=`${amount} wood`}else if(n.type==='rock'){amount=2;player.stone+=amount;label='2 stone'}else if(n.type==='fiber'){amount=2;player.fiber+=amount;player.thatch+=1;label='fiber & thatch'}else if(n.type==='berry'){amount=3;player.berries+=amount;label='3 berries'}else if(n.type==='spring'){if(player.hasFlask&&player.water>=10){showToast('Your flask is full');return}amount=player.hasFlask?5:3;player.water=Math.min(player.hasFlask?20:10,player.water+amount);label='fresh water'}n.alive=false;for(let i=0;i<6;i++)particles.push({x:n.x,y:n.y,vx:rand(-45,45),vy:rand(-70,-15),life:rand(.35,.8),max:.8,color:n.type==='tree'?'#d9c67c':n.type==='rock'?'#d5d4c6':n.type==='berry'?'#b2675a':'#d7e4c0'});showToast(`Gathered ${label}`);addLog(`Collected ${label}.`);updateUI()}
function interact(){if(!gameStarted){resetGame();return}if(gameEnded)return;const t=nearestTarget();if(t&&t.dist<84)gather();else if(nearestDino(72))attack();else showToast('Move closer to a resource')}
function nearestDino(range=90){let best=null,distance=range;for(const d of dinos){if(!d.alive)continue;let v=Math.hypot(d.x-player.x,d.y-player.y);if(v<distance){best=d;distance=v}}return best?{dino:best,distance}:null}
function attack(){if(!player.hasSpear){showToast('Craft a stone spear first');return}const t=nearestDino(105);if(!t){showToast('No dinosaur in reach');return}const d=t.dino;d.hp--;d.alert=5;d.x+=((d.x-player.x)/(t.distance||1))*22;attackFlash=.16;for(let i=0;i<7;i++)particles.push({x:d.x,y:d.y,vx:rand(-75,75),vy:rand(-65,30),life:.4,max:.4,color:'#c77761'});if(d.hp<=0){d.alive=false;player.berries+=2;showToast('Dinosaur driven off · found 2 berries');addLog('Drove off a hungry dinosaur.');}else{showToast(`Spear strike · ${d.hp} hit${d.hp===1?'':'s'} left`)}updateUI()}
function placeBuild(x,y){const r=Math.hypot(x-player.x,y-player.y);if(r>150){showToast('Build closer to your position');return}if(!inIsland(x,y,20)){showToast('That spot is too close to the shore');return}if(buildings.some(b=>Math.hypot(x-b.x,y-b.y)<52)){showToast('There is something in the way');return}const recipe=recipes.find(a=>a.id===selectedBuild);if(!canPay(recipe.cost)){showToast(`Need ${costText(recipe.cost)}`);return}pay(recipe.cost);buildings.push({type:selectedBuild,x,y,angle:player.dirX?Math.atan2(player.dirY,player.dirX):0,health:3});showToast(`${recipe.name} built`);addLog(`Built a ${recipe.name.toLowerCase()}.`);if(selectedBuild==='shelter'&&elapsed>80)ui.objective.textContent='Shelter complete · survive until dawn';updateUI()}
function pointerPosition(e){const rect=canvas.getBoundingClientRect();return{x:e.clientX-rect.left,y:e.clientY-rect.top}}
canvas.addEventListener('click',e=>{if(!gameStarted||gameEnded)return;const p=pointerPosition(e),wx=player.x+p.x-W/2,wy=player.y+p.y-H/2;const t=nearestTarget();if(t&&t.dist<75){gather();return}placeBuild(wx,wy)});
