function pathEllipse(cx,cy,rx,ry,scale,phase=0){ctx.beginPath();for(let i=0;i<=72;i++){const a=i/72*Math.PI*2;const wave=1+scale*(Math.sin(a*5+phase)*.008+Math.sin(a*9+phase*1.7)*.006+Math.cos(a*3-phase)*.004);const x=cx+Math.cos(a)*rx*wave,y=cy+Math.sin(a)*ry*wave;if(i===0)ctx.moveTo(x,y);else ctx.lineTo(x,y)}ctx.closePath()}
