  const offset=(elapsed*7)%86;for(let y=-100+offset;y<H+100;y+=86)for(let x=30;x<W;x+=128){ctx.beginPath();ctx.arc(x+Math.sin(y)*16,y,rand(12,21),.15,2.7);ctx.stroke()};ctx.restore();
  const cx=W/2-player.x,cy=H/2-player.y;
