  // Light variation in the island's mossy ground.
  ctx.save();pathEllipse(cx,cy,world.rx-50,world.ry-44,.7,1);ctx.clip();ctx.globalAlpha=.08;for(let i=0;i<75;i++){let p=islandPoint(.05,.94);ctx.fillStyle=i%2?'#ddd38d':'#3e6349';ctx.beginPath();ctx.ellipse(cx+p.x,cy+p.y,rand(22,95),rand(8,28),rand(0,3),0,Math.PI*2);ctx.fill()}ctx.restore();
  // Occasional sand paths and flower flecks.
  ctx.save();ctx.globalAlpha=.25;ctx.strokeStyle='#d9cc9e';ctx.lineWidth=13;ctx.lineCap='round';ctx.beginPath();ctx.moveTo(cx+220,cy-340);ctx.quadraticCurveTo(cx+60,cy-180,cx+150,cy+45);ctx.stroke();ctx.restore();
}
function shade(x,y,rx,ry,alpha=.19){ctx.save();ctx.globalAlpha=alpha;ctx.fillStyle='#203326';ctx.beginPath();ctx.ellipse(x,y,rx,ry,0,0,Math.PI*2);ctx.fill();ctx.restore()}
function drawTree(n){const s=n.scale,x=n.x,y=n.y;shade(x+4,y+11,19*s,8*s,.22);ctx.fillStyle='#6b5030';ctx.fillRect(x-4*s,y-8*s,8*s,19*s);ctx.strokeStyle='#9b7745';ctx.lineWidth=2*s;ctx.beginPath();ctx.moveTo(x,y+5*s);ctx.lineTo(x-10*s,y+14*s);ctx.moveTo(x+1*s,y+4*s);ctx.lineTo(x+10*s,y+13*s);ctx.stroke();const colors=['#365d3c','#426b41','#4f7547'];for(let i=0;i<3;i++){ctx.fillStyle=colors[(i+n.variant)%3];ctx.beginPath();ctx.arc(x+(i-1)*11*s,y-15*s+(i%2)*4*s,15*s,0,Math.PI*2);ctx.fill()}ctx.fillStyle='#6c8c50';ctx.beginPath();ctx.arc(x-5*s,y-22*s,9*s,0,Math.PI*2);ctx.fill();ctx.fillStyle='#a5af69';ctx.globalAlpha=.45;ctx.beginPath();ctx.arc(x-9*s,y-27*s,4*s,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1}
function drawRock(n){const s=n.scale,x=n.x,y=n.y;shade(x,y+8*s,16*s,7*s,.16);ctx.fillStyle='#7b8171';ctx.beginPath();ctx.moveTo(x-16*s,y+7*s);ctx.lineTo(x-13*s,y-6*s);ctx.lineTo(x-3*s,y-14*s);ctx.lineTo(x+10*s,y-12*s);ctx.lineTo(x+17*s,y+2*s);ctx.lineTo(x+11*s,y+10*s);ctx.closePath();ctx.fill();ctx.fillStyle='#a4a795';ctx.beginPath();ctx.moveTo(x-11*s,y-6*s);ctx.lineTo(x-3*s,y-14*s);ctx.lineTo(x+7*s,y-11*s);ctx.lineTo(x+1*s,y-4*s);ctx.closePath();ctx.fill();ctx.strokeStyle='#626c62';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(x+3*s,y-3*s);ctx.lineTo(x+10*s,y+3*s);ctx.stroke()}
function drawBerry(n){const s=n.scale,x=n.x,y=n.y;shade(x,y+7*s,14*s,6*s,.14);ctx.fillStyle='#547a49';ctx.beginPath();ctx.ellipse(x,y,12*s,8*s,0,0,Math.PI*2);ctx.fill();for(let i=0;i<5;i++){ctx.fillStyle=i%2?'#bd6557':'#d07861';ctx.beginPath();ctx.arc(x+Math.cos(i*1.25)*8*s,y+Math.sin(i*1.25)*5*s,3.2*s,0,Math.PI*2);ctx.fill()}}
function drawFiber(n){const x=n.x,y=n.y,s=n.scale;shade(x,y+5,11*s,4*s,.12);ctx.strokeStyle='#b9aa67';ctx.lineWidth=2*s;for(let i=0;i<4;i++){ctx.beginPath();ctx.moveTo(x+(i-2)*3*s,y+6*s);ctx.quadraticCurveTo(x+(i-2)*9*s,y-9*s,x+(i-2)*5*s,y-17*s);ctx.stroke()}ctx.fillStyle='#8c9955';ctx.beginPath();ctx.arc(x,y+1,7*s,0,Math.PI*2);ctx.fill()}
function drawSpring(n){ctx.save();ctx.globalAlpha=.78;ctx.fillStyle='#cfbf88';ctx.beginPath();ctx.ellipse(n.x,n.y,27,19,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#70b2b1';ctx.beginPath();ctx.ellipse(n.x,n.y,20,13,0,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#c3e1cf';ctx.lineWidth=1.5;ctx.beginPath();ctx.arc(n.x,n.y,7+Math.sin(elapsed*3)*2,0,Math.PI*2);ctx.stroke();ctx.restore()}

