function drawSpring(n){ctx.save();ctx.globalAlpha=.78;ctx.fillStyle='#cfbf88';ctx.beginPath();ctx.ellipse(n.x,n.y,27,19,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#70b2b1';ctx.beginPath();ctx.ellipse(n.x,n.y,20,13,0,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#c3e1cf';ctx.lineWidth=1.5;ctx.beginPath();ctx.arc(n.x,n.y,7+Math.sin(elapsed*3)*2,0,Math.PI*2);ctx.stroke();ctx.restore()}
function drawDino(d){if(!d.alive)return;const x=d.x,y=d.y,s=d.scale;ctx.save();ctx.translate(x,y);ctx.rotate(d.angle);shade(1,11,26*s,8*s,.24);const body=d.alert>0?'#697744':'#778451';ctx.fillStyle=body;ctx.beginPath();ctx.ellipse(0,0,23*s,12*s,0,0,Math.PI*2);ctx.fill();ctx.beginPath();ctx.moveTo(-17*s,-2*s);ctx.quadraticCurveTo(-31*s,-4*s,-44*s,-10*s);ctx.quadraticCurveTo(-38*s,1*s,-20*s,6*s);ctx.fill();ctx.beginPath();ctx.ellipse(19*s,-7*s,10*s,7*s,-.25,0,Math.PI*2);ctx.fill();ctx.fillStyle='#d2c68d';ctx.beginPath();ctx.ellipse(26*s,-5*s,5*s,2.2*s,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#202e26';ctx.beginPath();ctx.arc(22*s,-9*s,1.8*s,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#49583b';ctx.lineWidth=3*s;ctx.beginPath();ctx.moveTo(-7*s,7*s);ctx.lineTo(-8*s,15*s);ctx.lineTo(-13*s,16*s);ctx.moveTo(11*s,7*s);ctx.lineTo(13*s,14*s);ctx.lineTo(9*s,16*s);ctx.stroke();ctx.fillStyle='#9fa06a';for(let i=0;i<4;i++){ctx.beginPath();ctx.moveTo((-8+i*7)*s,-10*s);ctx.lineTo((-5+i*7)*s,-16*s);ctx.lineTo((-2+i*7)*s,-9*s);ctx.fill()}ctx.restore();if(d.alert>0&&Math.hypot(d.x-player.x,d.y-player.y)<270){ctx.fillStyle='#f0d7a2';ctx.font='12px sans-serif';ctx.textAlign='center';ctx.fillText('!',x,y-27)}}
function drawPlayer(){const x=player.x,y=player.y;shade(x,y+13,12,6,.25);ctx.save();ctx.translate(x,y);ctx.rotate(Math.atan2(player.dirY,player.dirX)+Math.PI/2);ctx.fillStyle='#314436';ctx.beginPath();ctx.ellipse(0,2,9,13,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#c58b63';ctx.beginPath();ctx.arc(0,-11,6.6,0,Math.PI*2);ctx.fill();ctx.fillStyle='#d7cfac';ctx.beginPath();ctx.moveTo(-7,-2);ctx.lineTo(0,-5);ctx.lineTo(7,-2);ctx.lineTo(6,5);ctx.lineTo(-6,5);ctx.closePath();ctx.fill();ctx.fillStyle='#b8a06a';ctx.fillRect(-7,-4,14,2);if(player.hasSpear){ctx.strokeStyle='#e3d8b7';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(8,0);ctx.lineTo(14,-17);ctx.stroke();ctx.fillStyle='#c6c2a9';ctx.beginPath();ctx.moveTo(14,-21);ctx.lineTo(11,-15);ctx.lineTo(16,-15);ctx.fill()}ctx.restore();if(attackFlash>0){ctx.strokeStyle='#f3dfaa';ctx.lineWidth=2;ctx.beginPath();ctx.arc(x,y,30,-1.7,-.5);ctx.stroke()}}
function drawBuilding(b){ctx.save();ctx.translate(b.x,b.y);if(b.type==='campfire'){shade(0,10,23,9,.24);ctx.fillStyle='#777364';for(let i=0;i<8;i++){const a=i*Math.PI/4;ctx.beginPath();ctx.ellipse(Math.cos(a)*15,Math.sin(a)*8,5,3,a,0,Math.PI*2);ctx.fill()}ctx.fillStyle='#5e4930';ctx.lineWidth=4;ctx.beginPath();ctx.moveTo(-9,2);ctx.lineTo(9,-2);ctx.moveTo(-6,-4);ctx.lineTo(7,5);ctx.stroke();const flame=.8+Math.sin(elapsed*8)*.16;ctx.fillStyle='#d48948';ctx.beginPath();ctx.moveTo(0,-2);ctx.quadraticCurveTo(-11,-15,-2,-23*flame);ctx.quadraticCurveTo(2,-17,4,-12);ctx.quadraticCurveTo(13,-22,9,-3);ctx.closePath();ctx.fill();ctx.fillStyle='#f2ca70';ctx.beginPath();ctx.moveTo(2,-2);ctx.quadraticCurveTo(-5,-10,1,-17);ctx.quadraticCurveTo(8,-10,5,-2);ctx.fill();ctx.globalAlpha=.2;ctx.fillStyle='#edc879';ctx.beginPath();ctx.arc(0,-8,27+Math.sin(elapsed*5)*4,0,Math.PI*2);ctx.fill()}else if(b.type==='wall'){ctx.rotate(b.angle);shade(0,10,28,8,.18);ctx.fillStyle='#694e34';ctx.fillRect(-25,-8,50,16);ctx.fillStyle='#9a7548';for(let i=-2;i<=2;i++){ctx.fillRect(i*9-3,-14,6,27)}ctx.fillStyle='#b09564';ctx.fillRect(-25,-13,50,5);ctx.fillRect(-25,7,50,4)}else{shade(0,14,28,11,.2);ctx.fillStyle='#795b39';ctx.fillRect(-25,-5,50,25);ctx.fillStyle='#ad9460';ctx.beginPath();ctx.moveTo(-30,-4);ctx.lineTo(0,-27);ctx.lineTo(30,-4);ctx.closePath();ctx.fill();ctx.fillStyle='#6e7548';ctx.beginPath();ctx.moveTo(-32,-7);ctx.lineTo(0,-32);ctx.lineTo(32,-7);ctx.lineTo(25,-3);ctx.lineTo(0,-24);ctx.lineTo(-26,-3);ctx.closePath();ctx.fill();ctx.fillStyle='#3d4d36';ctx.fillRect(-5,7,10,13)}ctx.restore()}
function drawNode(n){if(!n.alive)return;if(n.type==='tree')drawTree(n);else if(n.type==='rock')drawRock(n);else if(n.type==='berry')drawBerry(n);else if(n.type==='fiber')drawFiber(n);else drawSpring(n)}
function drawScene(){if(!W||!H)return;ctx.setTransform(dpr,0,0,dpr,0,0);drawIsland();ctx.save();ctx.translate(W/2-player.x,H/2-player.y);const items=[];for(const n of nodes)if(n.alive)items.push({y:n.y,draw:()=>drawNode(n)});for(const d of dinos)if(d.alive)items.push({y:d.y,draw:()=>drawDino(d)});for(const b of buildings)items.push({y:b.y+10,draw:()=>drawBuilding(b)});items.push({y:player.y+10,draw:drawPlayer});items.sort((a,b)=>a.y-b.y);for(const o of items)o.draw();for(const p of particles){ctx.globalAlpha=Math.max(0,p.life/p.max);ctx.fillStyle=p.color;ctx.beginPath();ctx.arc(p.x,p.y,2.5,0,Math.PI*2);ctx.fill()}ctx.globalAlpha=1;
  // Selected build placement ghost.
  const buildX=player.x+player.dirX*72,buildY=player.y+player.dirY*72;ctx.globalAlpha=.56;ctx.strokeStyle='#f2e7ba';ctx.lineWidth=2;ctx.setLineDash([5,4]);ctx.beginPath();ctx.arc(buildX,buildY,26,0,Math.PI*2);ctx.stroke();ctx.setLineDash([]);ctx.globalAlpha=1;ctx.restore();
  const target=nearestTarget();if(target&&target.dist<84){ui.prompt.classList.add('visible');ui.promptName.textContent=target.node.type==='tree'?'Tree':target.node.type==='rock'?'Stone':target.node.type==='berry'?'Wild berries':target.node.type==='spring'?'Fresh spring':'Wild fiber'};}else ui.prompt.classList.remove('visible');
  const menace=nearestDino(225);ui.threat.classList.toggle('visible',!!menace);if(menace)ui.threat.innerHTML='<span>!</span> SOMETHING IS NEAR';
}

