function movePlayer(dt){let x=(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0)+joystick.x,y=(keys.s||keys.arrowdown?1:0)-(keys.w||keys.arrowup?1:0)+joystick.y;const len=Math.hypot(x,y);if(len>1){x/=len;y/=len}if(len>.05){player.dirX=x;player.dirY=y;const nx=player.x+x*player.speed*dt,ny=player.y+y*player.speed*dt;if(inIsland(nx,ny,31)){player.x=nx;player.y=ny}else{const tx=inIsland(nx,player.y,31),ty=inIsland(player.x,ny,31);if(tx)player.x=nx;if(ty)player.y=ny}}
