function updateDinos(dt){for(const d of dinos){if(!d.alive)continue;const dx=player.x-d.x,dy=player.y-d.y,dist=Math.hypot(dx,dy);if(dist<190)d.alert=4.5;else d.alert=Math.max(0,d.alert-dt);if(d.alert>0&&dist>26){d.vx=dx/(dist||1);d.vy=dy/(dist||1)}else if(d.alert<=0){d.roam-=dt;if(d.roam<=0){const a=rand(0,6.28);d.vx=Math.cos(a);d.vy=Math.sin(a);d.roam=rand(1.2,3.8)}}if(d.alert>0&&dist<30){d.attack-=dt;if(d.attack<=0){const protectedFire=buildings.some(b=>b.type==='campfire'&&Math.hypot(player.x-b.x,player.y-b.y)<83);player.health-=protectedFire?3:12;d.attack=1.15;showToast(protectedFire?'The fire keeps it back!':'A dinosaur tore into you!');if(!protectedFire){player.x+=dx/(dist||1)*20;player.y+=dy/(dist||1)*20}}}d.angle=Math.atan2(d.vy,d.vx);const nx=d.x+d.vx*d.speed*dt*(d.alert>0?1.18:.45),ny=d.y+d.vy*d.speed*dt*(d.alert>0?1.18:.45);if(inIsland(nx,ny,50)){d.x=nx;d.y=ny}else{d.vx*=-1;d.vy*=-1;d.roam=0}for(const b of buildings)if(b.type==='wall'&&Math.hypot(d.x-b.x,d.y-b.y)<34){d.x-=d.vx*45*dt;d.y-=d.vy*45*dt}}
